    for i in range(H_A):
        for j in range(W_A):
            if A_i[j] == '#':
                sheet_C[i + H_A - 1 - H_A * (j // W_A)][j % W_A] = '.'
    for i in range(H_B):
        for j in range(W_B):
            if B_i[j] == '#':
                sheet_C[i + H_B - 1 - H_B * (j // W_B)][j % W_B] = '.'

    # Cut out a 5x3 area with the square in the first row and second column of the range illustrated above as the top-left corner
    for i in range(H_X):
        for j in range(W_X):
            if sheet_C[i + H_X - 1 - H_X * (j // W_X)][j % W_X] == '#':
                sheet_C[i + H_X - 1 - H_X * (j // W_X)][j % W_X] = '.'

