    for i in range(H_A):
        for j in range(W_A):
            if sheet_C[i + H_A - 1 - H_A * (j // W_A)][j % W_A] != '.':
                return False
    for i in range(H_B):
        for j in range(W_B):
            if sheet_C[i + H_B - 1 - H_B * (j // W_B)][j % W_B] != '.':
                return False

    # Check if the cut-out sheet coincides sheet X without rotating or flipping
    for i in range(H_X):
        for j in range(W_X):
            if sheet_C[i + H_X - 1 - H_X * (j // W_X)][j % W_X] != '.':
                return False

    return True

