def choose_days(N, D):
    schedule = [input() for _ in range(N)]
    free_days = set()
    for i in range(N):
        for j in range(D):
            if schedule[i][j] == 'o':
                free_days.add(j)
    chosen_days = set()
    for i in range(N):
        for j in range(D):
            if schedule[i][j] == 'o' and j not in free_days:
                chosen_days.add(j)
    return len(chosen_days)

def find_directed_cycle(n, a):
    graph = {}
    for i in range(n):
        graph[i] = set()
    for i in range(n):
        for j in range(n):
            if i != j and a[i] == a[j]:
                graph[i].add(j)
    visited = set()
    stack = set()
    for i in range(n):
        if i not in visited:
            visited.add(i)
            stack.add(i)
            while stack:
                u = stack.pop()
                for v in graph[u]:
                    if v not in visited:
                        visited.add(v)
                        stack.add(v)
    return visited

