def find_min_cost(N, M, K):
    edges = []
    for i in range(1, N+1):
        for j in range(1, N+1):
            if i != j:
                edges.append((i, j, i*j % K))
    spanning_tree = set()
    for i in range(1, N+1):
        spanning_tree.add(i)
    cost = 0
    while len(spanning_tree) > 1:
        min_cost = float('inf')
        for edge in edges:
            if edge[0] in spanning_tree and edge[1] in spanning_tree:
                cost += edge[2]
                spanning_tree.remove(edge[0])
                spanning_tree.remove(edge[1])
                break
        if cost < min_cost:
            min_cost = cost
    return min_cost

