def find_min_moves(n, s1, s2):
    if n < 2 or len(s1) != len(s2):
        return -1

    players = [s1, s2]
    visited = set()
    moves = 0

    while True:
        for i, player in enumerate(players):
            for j, cell in enumerate(player):
                if cell == 'P':
                    if (i, j) in visited:
                        return -1
                    visited.add((i, j))
                    if (i, j) == (0, 0):
                        return moves
                    for dir in [(0, -1), (-1, 0), (0, 1), (1, 0)]:
                        new_i, new_j = i + dir[0], j + dir[1]
                        if 0 <= new_i < n and 0 <= new_j < n and players[0][new_i][new_j] == '.' and (new_i, new_j) not in visited:
                            players[0][new_i][new_j] = 'P'
                            players[1][new_i][new_j] = 'P'
                            visited.add((new_i, new_j))
                            moves += 1
                            break
        if len(visited) == n * n:
            return moves

