            tallest_building = heights[i]
    return tallest_building

def longest_common_prefix(s1, s2):
    common_prefix = ""
    for i in range(min(len(s1), len(s2))):
        if s1[i] == s2[i]:
            common_prefix += s1[i]
        else:
            break
    return common_prefix

def sum_of_f(s1, s2):
    return sum(len(longest_common_prefix(s1, s2)) for s1, s2 in zip(s1, s2))

