def generate_remaining_cards(n, a, c):
    m = 0
    i = 0
    while i < n:
        if a[i] > a[i+1] and c[i] < c[i+1]:
            i += 1
        else:
            m += 1
            i += 1
    return m, sorted(range(i, n), key=lambda x: (a[x], c[x]))

def check_consecutive_elements(A, B):
    A.sort()
    B.sort()
    for i in range(len(A)):
        if A[i] != B[i]:
            return False
    return True

