def bingo(n, t, a):
    grid = [[0 for _ in range(n)] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            grid[i][j] = n * (i - 1) + j
    for i in range(t):
        a_i = a[i]
        for j in range(n):
            if grid[j][a_i - 1] == 0:
                grid[j][a_i - 1] = a_i
                break
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 0:
                return -1
    for i in range(n):
        for j in range(n):
            if grid[i][j] == n * (i - 1) + j:
                return i * n + j
    return -1

