def find_shortest_substring(arr):
    answer = []
    for i, s in enumerate(arr):
        if s not in arr[:i] + arr[i+1:]:
            answer.append(s)
    return answer

def most_frequent_id(nums, freq):
    ans = [0] * len(nums)
    for i, num in enumerate(nums):
        if freq[i] > 0:
            ans[i] += 1
        elif freq[i] < 0:
            ans[i] -= 1
    return ans

def find_longest_common_suffix(wordsContainer, wordsQuery):
    ans = []
    for i, word in enumerate(wordsQuery):
        common_suffix = set(word)
        for j, word_container in enumerate(wordsContainer):
            if word_container.startswith(common_suffix):
                ans.append(j)
                break
    return ans

def minCost(nums, cost1, cost2):
    total_cost = 0
    for num in nums:
        total_cost += min(cost1, cost2)
    return total_cost % (10**9 + 7)

