def count_right_triangles(grid):
    num_triangles = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                for k in range(len(grid[0])):
                    if grid[i][k] == 1 and grid[k][j] == 1:
                        num_triangles += 1
    return num_triangles

def powerful_array(x):
    big_nums = []
    while True:
        big_nums.append(2 ** i)
        i += 1
        if i > x:
            break
    return big_nums

def query_product(from_i, to_i, mod_i):
    return (big_nums[from_i] * big_nums[from_i + 1] * ... * big_nums[to_i]) % mod_i

def solve(queries):
    answer = []
    for from_i, to_i, mod_i in queries:
        answer.append(query_product(from_i, to_i, mod_i))
    return answer
